insert into public.tipos_laudo (id, codigo, nome, descricao, ordem, ativo) values
  ('bdb64354-ba12-5f93-812c-9b36d31171e3', 'criminal', 'Criminal (perícia médico-legal)', 'Laudo médico-pericial criminal conforme a diretriz da ABMLPM: preâmbulo, quesitos, histórico, descrição do exame, inventário de lesões, agente/mecanismo lesional, exames complementares, nexo causal, repercussões do dano (qualificadoras do art. 129 CP) e módulos condicionais por natureza do exame (violência sexual, toxicologia/embriaguez, sanidade mental/imputabilidade, integridade física/custódia, morte/causa mortis, alegada falha assistencial com repercussão criminal).', 7, true);
