  ('2a06f1d9-43a4-513e-8644-79aae0be2391', 'bdb64354-ba12-5f93-812c-9b36d31171e3', 'modulo_violencia_sexual', 'XIII-A — Violência Sexual', 13, true, '{"campo_codigo": "modalidade_principal", "valores_gatilho": ["violencia_sexual"]}'::jsonb, null),
